INSERT INTO `movies` (`id`, `title`, `description`, `genre`, `duration_minutes`, `format`, `poster_path`, `trailer_url`, `rating`, `release_date`, `end_date`, `is_showing`, `created_at`, `updated_at`) VALUES
(10, 'INSIDE OUT', 'Inside Out adalah film animasi dari Pixar Animation Studios dan Walt Disney Pictures yang menceritakan seorang gadis berusia 11 tahun bernama Riley yang harus pindah dari kehidupan nyamannya ke kota baru. Di dalam pikirannya terdapat lima emosi utama—Joy (Bahagia), Sadness (Sedih), Anger (Marah), Fear (Takut), dan Disgust (Jijik)—yang bekerja mengendalikan perasaan dan tindakannya. Ketika Joy dan Sadness tersesat jauh di dalam pikiran Riley, emosi lainnya harus berusaha menjaga hidup Riley tetap berjalan.', 'animasi', 96, '2D', 'https://image.tmdb.org/t/p/w500/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg', 'https://youtu.be/yRUAzGQ3nSY?si=N6TIakKQpHuTADzZ', 0, '2026-07-30', '2026-08-30', 1, '2026-06-10 03:40:07', '2026-07-30 06:34:06'),
(11, 'GONE GIRL', 'Gone Girl adalah film thriller psikologis yang menceritakan Nick Dunne, seorang pria yang melaporkan hilangnya istrinya, Amy Dunne, tepat pada hari ulang tahun pernikahan mereka yang kelima. Seiring penyelidikan berlangsung dan sorotan media semakin besar, banyak kejanggalan mulai terungkap. Nick perlahan menjadi tersangka utama dalam kasus tersebut, sementara berbagai rahasia tentang hubungan mereka mulai terbuka. Film ini penuh misteri, manipulasi, dan plot twist yang membuat penonton terus menebak-nebak hingga akhir.', 'Mystery', 149, '2D', 'https://image.tmdb.org/t/p/w500/ts996lKsxvjkO2yiYG0ht4qAicO.jpg', 'https://youtu.be/2-_-1nJf8Vg?si=JyhhYiFVakINFnJa', 0, '2026-07-30', '2026-08-30', 1, '2026-06-10 03:47:20', '2026-07-30 06:33:50'),
(12, 'INTERSTELLAR', 'Interstellar adalah film fiksi ilmiah yang menceritakan masa depan Bumi yang sedang mengalami krisis pangan dan lingkungan. Mantan pilot NASA bernama Cooper menerima misi untuk melakukan perjalanan melintasi galaksi melalui sebuah lubang cacing (wormhole) guna mencari planet baru yang dapat dihuni manusia.\r\n\r\nDalam perjalanannya, Cooper dan tim ilmuwan menghadapi berbagai tantangan luar biasa, termasuk fenomena relativitas waktu, planet-planet yang berbahaya, serta dilema antara menyelamatkan umat manusia dan kembali kepada keluarga yang ditinggalkannya di Bumi. Film ini menggabungkan petualangan luar angkasa, konsep fisika modern, dan kisah emosional tentang keluarga, harapan, serta pengorbanan.', 'Science Fiction', 169, '2D', 'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', 'https://youtu.be/zSWdZVtXT7E?si=yJ2RCcY1fUEAklTs', 8.7, '2026-07-30', '2026-08-30', 1, '2026-06-10 03:52:40', '2026-07-30 06:33:36'),
(13, 'FILM TEST', 'FILLM TEST it was the most creepy film in every universe EDAN', 'bahaya', 128, '2D', 'C:\\Users\\gugum\\Pictures\\Screenshots\\Screenshot 2025-05-30 193811.png', '', 0, '2026-07-29', '2026-08-30', 1, '2026-06-21 06:30:28', '2026-10-08 18:24:15'),
(14, 'ada lah', 'itu lah', 'disappointed, wondering, thinking', 60, 'IMAX', 'https://res.cloudinary.com/dxqbh2km8/image/upload/v1785437588/cinecore/posters/ojmh0q8o49aydrepywpj.png', NULL, 0, '2026-07-31', '2026-08-08', 1, '2026-07-30 11:53:09', '2026-07-30 11:53:09');

